#pragma once
static void checkNmrParallel(App& app,const std::string& fixture,const std::string& dir){
    auto require=[](bool value,const char* why){if(!value)throw std::runtime_error(why);};
    std::ofstream log(dir+"/checks.txt");
    TabHost host;host.inst=GetModuleHandleW(0);host.factory=[&](HWND parent,const std::string& path,bool demo){return createEditorTab(host.inst,parent,path,demo);};
    auto pump=[](){MSG msg;while(PeekMessageW(&msg,0,0,0,PM_REMOVE)){if(msg.message==WM_QUIT)continue;TranslateMessage(&msg);DispatchMessageW(&msg);}};
    auto tabLabel=[](NmrDialog& dialog,int index){wchar_t label[160]={};TCITEMW item={};item.mask=TCIF_TEXT;item.pszText=label;item.cchTextMax=160;SendMessageW(dialog.tabs,TCM_GETITEMW,index,LPARAM(&item));return std::wstring(label);};
    auto until=[&](const std::function<bool()>& done,int milliseconds){double end=App::now()+milliseconds;while(!done()&&App::now()<end){pump();std::this_thread::sleep_for(std::chrono::milliseconds(2));}pump();require(done(),"timed out waiting for NMR jobs");};
    struct Round {std::atomic<int> calls[3],active,peak;std::atomic<bool> release[3];int outcome[3];std::string actions[3];Round():active(0),peak(0){for(int i=0;i<3;++i){calls[i]=0;release[i]=false;outcome[i]=0;}}};
    auto predictor=[](std::shared_ptr<Round> round){return [round](const std::string& action,std::string* result,const std::atomic<bool>* cancel){int i=action.find("nmr13c")==0?1:action.find("nmr19f")==0?2:0;round->actions[i]=action;++round->calls[i];int active=++round->active,peak=round->peak;while(peak<active&&!round->peak.compare_exchange_weak(peak,active)){}while(!round->release[i]&&!cancel->load())std::this_thread::sleep_for(std::chrono::milliseconds(2));--round->active;if(cancel->load())return false;if(round->outcome[i]==1){*result="当前结构不含氟原子，无需预测氟谱";return false;}const char* name=round->outcome[i]==2?"1H":NmrDialog::predictionNucleus(i);*result=std::string("NMR")+name+"\t1\nmapping\t1\nformula\tRendering fixture\ncoverage\t1\t1\nsolvent\t"+(action.find("dmso-d6")!=std::string::npos?"dmso-d6":"cdcl3")+"\npeak\t"+std::to_string(1+i*20)+"\t1\t10\t—\tRendering fixture\tgood\n";return true;};};
    try{
        host.create();host.newTab();App* editor=host.tabs.front();editor->testing=true;
        const std::string source="<CDXML BondLength='20'><page id='1'><fragment id='2'><n id='10' p='0 0' Element='6'/><n id='11' p='20 0' Element='8'/><b id='12' B='10' E='11'/></fragment></page></CDXML>";
        editor->openNmrTab(source);App* page=host.tabs.back();page->testing=true;auto& nmr=*page->nmrPage;auto round=std::make_shared<Round>();round->outcome[2]=1;nmr.asyncPredictor=predictor(round);
        until([&](){return round->active==3;},1000);require(round->peak==3&&nmr.batchStarted,"all nuclei start before any tab click");for(int i=0;i<3;++i)require(tabLabel(nmr,i).find(L"计算中")!=std::wstring::npos,"each tab displays its running state");auto jobs=std::vector<std::shared_ptr<NmrDialog::PredictionJob>>(nmr.predictionJobs,nmr.predictionJobs+3);
        nmr.loadTab(page->nmrChild,1);nmr.loadTab(page->nmrChild,2);nmr.loadTab(page->nmrChild,0);for(int i=0;i<3;++i)require(round->calls[i]==1&&!jobs[i]->cancelled,"switching tabs neither restarts nor cancels work");
        auto sourceBefore=editor->s.doc.digest();host.selectTab(0);ObjectId added;require(editor->s.submit(commands::addAtom(Vec2(5,10),6,&added),"edit during parallel NMR").ok()&&editor->s.doc.digest()!=sourceBefore,"source editable during all predictions");require(nmr.source==source,"prediction snapshot stays fixed");
        round->release[1]=true;until([&](){return nmr.completed[1];},1000);require(nmr.activeTab==0&&nmr.loading&&host.active==0,"carbon finishes without replacing active H or stealing source focus");
        host.selectTab(1);nmr.loadTab(page->nmrChild,1);require(nmr.carbon&&!nmr.loading&&!nmr.peaks.empty(),"carbon ready before user selects it");auto structure=nmr.structure;nmr.chartZoom=2;nmr.structureZoom=1.5;
        round->release[0]=true;round->release[2]=true;until([&](){return !nmr.pendingPredictions();},1000);require(nmr.carbon&&nmr.chartZoom==2&&nmr.structureZoom==1.5,"inactive results preserve current nucleus and preview view");require(nmr.completed[0]&&nmr.completed[1]&&!nmr.completed[2]&&NmrDialog::absentNucleus(nmr.failures[2]),"missing nucleus isolated and remembered");require(tabLabel(nmr,0).find(L"已完成")!=std::wstring::npos&&tabLabel(nmr,1).find(L"已完成")!=std::wstring::npos&&tabLabel(nmr,2).find(L"不适用")!=std::wstring::npos,"per-nucleus terminal status displayed");
        for(int i=0;i<8;++i){nmr.loadTab(page->nmrChild,2);require(!nmr.loading&&!nmr.errorMessage.empty(),"absent F returns cached explanation");nmr.loadTab(page->nmrChild,0);nmr.loadTab(page->nmrChild,1);}require(nmr.structure==structure,"annotated structure reused on tab revisit");for(int i=0;i<3;++i)require(round->calls[i]==1,"cache hits never run models again");
        SetWindowTextW(GetDlgItem(page->nmrChild,734),L"600");nmr.applyConditions(page->nmrChild);require(nmr.protonMHz==600&&!nmr.pendingPredictions()&&round->calls[0]==1,"frequency change reuses ppm results");
        log<<"automatic_all=1 max_parallel="<<round->peak<<" cache_hits=1 absent_cached=1 source_edit=1 focus_retained=1 frequency_reuses_results=1\n";log.flush();
        // Two solvent generations: cancel all old work and reject delayed results.
        auto oldRound=std::make_shared<Round>();nmr.asyncPredictor=predictor(oldRound);SendMessageW(GetDlgItem(page->nmrChild,732),CB_SETCURSEL,2,0);nmr.applyConditions(page->nmrChild);until([&](){return oldRound->active==3;},1000);auto oldJobs=std::vector<std::shared_ptr<NmrDialog::PredictionJob>>(nmr.predictionJobs,nmr.predictionJobs+3);
        auto newRound=std::make_shared<Round>();newRound->outcome[1]=2;nmr.asyncPredictor=predictor(newRound);SendMessageW(GetDlgItem(page->nmrChild,732),CB_SETCURSEL,1,0);nmr.applyConditions(page->nmrChild);until([&](){return newRound->active==3;},1000);
        for(int i=0;i<3;++i){require(oldJobs[i]->cancelled,"solvent change cancels every old job");nmr.finishPrediction(page->nmrChild,oldJobs[i]->token);newRound->release[i]=true;}
        until([&](){return !nmr.pendingPredictions()&&oldRound->active==0;},1000);require(nmr.completed[0]&&nmr.completed[2]&&!nmr.completed[1]&&nmr.failures[1].find("核类型")!=std::string::npos,"malformed nucleus cannot enter another tab cache");require(nmr.solventIndex==1&&nmr.cached[0].find("solvent\tcdcl3")!=std::string::npos,"old solvent cannot replace new results");
        log<<"solvent_restarts_all=1 stale_rejected=1 failed_spectrum_isolated=1\n";log.flush();
        auto closing=std::make_shared<Round>();nmr.asyncPredictor=predictor(closing);SendMessageW(GetDlgItem(page->nmrChild,732),CB_SETCURSEL,2,0);nmr.applyConditions(page->nmrChild);until([&](){return closing->active==3;},1000);auto closingJobs=std::vector<std::shared_ptr<NmrDialog::PredictionJob>>(nmr.predictionJobs,nmr.predictionJobs+3);host.closeTab(page);pump();until([&](){for(const auto& job:closingJobs)if(!job->finished)return false;return true;},1000);for(const auto& job:closingJobs)require(job->cancelled,"closing NMR tab cancels all nuclei");require(host.tabs.size()==1&&host.tabs.front()==editor,"closing prediction preserves source");
        log<<"close_cancels_all=1\n";log.flush();
        if(std::getenv("MOLECULE_STUDIO_NMR_REAL_CHECK")){
            std::string xml=chemservice::read(W(fixture));editor->openNmrTab(xml);page=host.tabs.back();page->testing=true;auto& real=*page->nmrPage;double start=App::now();until([&](){return real.batchStarted;},1000);host.selectTab(0);require(IsWindowEnabled(editor->h)&&IsWindowEnabled(host.hwnd),"real backend keeps source enabled");until([&](){return !real.pendingPredictions();},42000);double elapsed=App::now()-start;
            for(int i=0;i<3;++i){require(real.completed[i],real.failures[i].c_str());require(real.cached[i].find("solvent\tcdcl3")!=std::string::npos,"real model solvent");real.loadTab(page->nmrChild,i);require(!real.loading&&!real.peaks.empty()&&real.structure,"real cached result has atom annotations");std::ofstream(dir+"/"+NmrDialog::predictionNucleus(i)+".tsv")<<real.cached[i];}
            require(host.active==0,"real prediction does not steal focus");for(int i=0;i<3;++i)require(tabLabel(real,i).find(L"已完成")!=std::wstring::npos,"real completion labels");
            host.selectTab(1);ShowWindow(host.hwnd,SW_SHOWNOACTIVATE);page->layout();UpdateWindow(page->h);UpdateWindow(page->nmrChild);
            {Bitmap image(page->width,page->height,PixelFormat32bppRGB);Graphics g(&image);page->paint(g);g.ResetTransform();RECT child;GetClientRect(page->nmrChild,&child);g.TranslateTransform(0.f,40*page->scale);real.paintContent(g,child.right,child.bottom);g.ResetTransform();HDC memory=g.GetHDC();for(HWND control=GetWindow(page->nmrChild,GW_CHILD);control;control=GetWindow(control,GW_HWNDNEXT)){if(!IsWindowVisible(control))continue;RECT cr;GetWindowRect(control,&cr);MapWindowPoints(nullptr,page->h,reinterpret_cast<POINT*>(&cr),2);int state=SaveDC(memory);SetViewportOrgEx(memory,cr.left,cr.top,nullptr);IntersectClipRect(memory,0,0,cr.right-cr.left,cr.bottom-cr.top);SendMessageW(control,WM_PRINT,WPARAM(memory),PRF_CLIENT|PRF_NONCLIENT|PRF_CHILDREN|PRF_ERASEBKGND);RestoreDC(memory,state);}g.ReleaseHDC(memory);UINT count=0,size=0;GetImageEncodersSize(&count,&size);std::vector<uint8_t> storage(size);auto codecs=reinterpret_cast<ImageCodecInfo*>(storage.data());GetImageEncoders(count,size,codecs);for(UINT i=0;i<count;++i)if(wcscmp(codecs[i].MimeType,L"image/png")==0)require(image.Save(W(dir+"/all-spectra-ready.png").c_str(),&codecs[i].Clsid,0)==Ok,"save real NMR preview");}
            ShowWindow(host.hwnd,SW_HIDE);host.selectTab(0);log<<"real_all_spectra=1 real_total_ms="<<elapsed<<"\n";log.flush();host.closeTab(page);pump();
            editor->openNmrTab(xml);page=host.tabs.back();page->testing=true;auto& cancel=*page->nmrPage;until([&](){return cancel.batchStarted;},1000);auto realJobs=std::vector<std::shared_ptr<NmrDialog::PredictionJob>>(cancel.predictionJobs,cancel.predictionJobs+3);double delay=App::now()+250;while(App::now()<delay){pump();std::this_thread::sleep_for(std::chrono::milliseconds(2));}start=App::now();host.closeTab(page);pump();until([&](){for(const auto& job:realJobs)if(!job->finished)return false;return true;},3000);for(const auto& job:realJobs)require(job->cancelled,"all real model workers cancelled");log<<"real_cancel_all=1 cancel_ms="<<App::now()-start<<"\n";log.flush();
        }
        editor->s.dirty=false;host.closeAll();host.reap();log<<"passed=1\n";
    }catch(const std::exception& e){std::ofstream(dir+"/failure.txt")<<e.what();for(auto page:host.tabs)page->s.dirty=false;host.closeAll();host.reap();}
    app.s.dirty=false;
}
